{
  "title": "The Ruined Crown",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "A small band gathers at the edge of the ruined city.",
      "visual_description": "Four travelers crouch on a windswept ridge at dusk, gazing down at a shattered skyline of broken spires and smoke. Tattered royal banners flap in the foreground.",
      "characters": ["Maren Vale", "Iska Thorn", "Bryn Holloway", "Old Pell"]
    },
    {
      "scene_number": 2,
      "caption": "Maren unrolls a map of the fallen capital.",
      "visual_description": "Close-up of a weathered parchment map weighed down by stones, lit by a single lantern. Maren's gloved finger traces a route past a tower marked with a red X.",
      "characters": ["Maren Vale", "Bryn Holloway"]
    },
    {
      "scene_number": 3,
      "caption": "Iska scouts ahead through a collapsed gate.",
      "visual_description": "A lithe scout slips between the iron teeth of a half-fallen portcullis, moonlight cutting across cracked flagstones and shattered statues of kings.",
      "characters": ["Iska Thorn"]
    },
    {
      "scene_number": 4,
      "caption": "The team meets a trembling townsperson hiding in a cellar.",
      "visual_description": "A soot-streaked woman clutches a child in a candlelit cellar of broken crockery, whispering to the kneeling rescuers. Shadows of patrolling boots pass the grate above.",
      "characters": ["Maren Vale", "Bryn Holloway", "Old Pell", "Goodwife Henna"]
    },
    {
      "scene_number": 5,
      "caption": "Rumors of a dragon stir argument among the group.",
      "visual_description": "Inside the cellar, Old Pell gestures wildly toward a charred scale on the table while Maren frowns. Firelight throws huge shadows on the stone walls.",
      "characters": ["Maren Vale", "Old Pell", "Iska Thorn"]
    },
    {
      "scene_number": 6,
      "caption": "They slip past an armored patrol in the market ruins.",
      "visual_description": "The team presses flat against a toppled fountain as black-plated soldiers with torches march through a moonlit plaza of broken stalls.",
      "characters": ["Maren Vale", "Iska Thorn", "Bryn Holloway", "Old Pell"]
    },
    {
      "scene_number": 7,
      "caption": "Bryn deciphers sigils on a sealed magic door.",
      "visual_description": "A tall arched door covered in glowing blue runes pulses softly. Bryn's hands hover over the symbols, her satchel of scrolls spilling at her feet.",
      "characters": ["Bryn Holloway", "Maren Vale"]
    },
    {
      "scene_number": 8,
      "caption": "The door opens onto a hall of broken thrones.",
      "visual_description": "A vast vaulted throne room with toppled chairs and shattered chandeliers, dust motes drifting in shafts of pale light through a collapsed ceiling.",
      "characters": ["Maren Vale", "Bryn Holloway", "Iska Thorn", "Old Pell"]
    },
    {
      "scene_number": 9,
      "caption": "Iska spots the cursed tower from a balcony.",
      "visual_description": "A high stone balcony overlooks a black tower wrapped in violet lightning. Iska crouches at the rail, her cloak whipping in the storm wind.",
      "characters": ["Iska Thorn"]
    },
    {
      "scene_number": 10,
      "caption": "Old Pell dozes through a critical briefing.",
      "visual_description": "A round, robed official snores against a pillar, hat askew, while the others lean over a chalk-drawn floor plan, exasperated.",
      "characters": ["Old Pell", "Maren Vale", "Bryn Holloway", "Iska Thorn"]
    },
    {
      "scene_number": 11,
      "caption": "They climb the cursed tower's spiral stair.",
      "visual_description": "A narrow spiral of worn stone steps lit by floating green witchlights. The rescuers ascend in single file, weapons drawn, shadows twisting unnaturally on the walls.",
      "characters": ["Maren Vale", "Iska Thorn", "Bryn Holloway", "Old Pell"]
    },
    {
      "scene_number": 12,
      "caption": "They find Prince Aldric chained in the tower's heart.",
      "visual_description": "A pale young man in tattered finery is shackled to a glowing altar in a circular chamber. Iron chains hum with red magic; the rescuers stop short in horror.",
      "characters": ["Prince Aldric", "Maren Vale", "Bryn Holloway"]
    },
    {
      "scene_number": 13,
      "caption": "Bryn breaks the binding spell.",
      "visual_description": "Bryn's hands blaze with white light as runes shatter outward from the altar. The prince gasps as chains crumble into red dust.",
      "characters": ["Bryn Holloway", "Prince Aldric", "Maren Vale"]
    },
    {
      "scene_number": 14,
      "caption": "Alarm bells ring across the ruined city.",
      "visual_description": "From a tower window, the group sees torches flooding the streets below and a great cracked bell swinging in a distant belfry, mouths open in alarm.",
      "characters": ["Maren Vale", "Iska Thorn", "Prince Aldric", "Old Pell"]
    },
    {
      "scene_number": 15,
      "caption": "A dragon's shadow sweeps over the rooftops.",
      "visual_description": "An enormous winged silhouette passes across the moon, briefly darkening the alley where the rescuers flatten themselves against a wall, faces pale with fear.",
      "characters": ["Maren Vale", "Iska Thorn", "Bryn Holloway", "Old Pell", "Prince Aldric"]
    },
    {
      "scene_number": 16,
      "caption": "Old Pell surprises everyone by opening a hidden way.",
      "visual_description": "The sleepy official taps a brick and a section of wall grinds aside, revealing a torch-lit stair down. He grins, suddenly sharp-eyed; the others stare.",
      "characters": ["Old Pell", "Maren Vale", "Bryn Holloway", "Iska Thorn", "Prince Aldric"]
    },
    {
      "scene_number": 17,
      "caption": "They race across the crumbling river bridge.",
      "visual_description": "A long stone bridge over a black river breaks apart behind running figures. Stones tumble into the water as patrol arrows streak through the night air.",
      "characters": ["Maren Vale", "Iska Thorn", "Bryn Holloway", "Old Pell", "Prince Aldric"]
    },
    {
      "scene_number": 18,
      "caption": "Safe on the far bank, they look back at the ruined crown.",
      "visual_description": "Five silhouettes stand on a misty hillside at dawn, the broken city smoldering across the river. A torn royal banner is planted in the grass beside them.",
      "characters": ["Maren Vale", "Iska Thorn", "Bryn Holloway", "Old Pell", "Prince Aldric"]
    }
  ]
}

